def git_blob(path: Path, root: Path) -> str:
    return subprocess.check_output(
        ["git", "-C", str(root), "hash-object", "--", str(path.relative_to(root))],
        text=True,
    ).strip()

def apply(root: Path) -> list[str]:
    changed: list[str] = []
    if set(EXPECTED_BLOBS) != set(REPLACEMENTS):
        raise SystemExit("internal path inventory mismatch")
    for relative in sorted(REPLACEMENTS):
        path = root / relative
        if not path.is_file():
            raise SystemExit(f"missing declared source file: {relative}")
        actual_blob = git_blob(path, root)
        expected_blob = EXPECTED_BLOBS[relative]
        if actual_blob != expected_blob:
            raise SystemExit(f"source drift for {relative}: expected {expected_blob}, got {actual_blob}")
        text = path.read_text(encoding="utf-8")
        original = text
        for index, (old, new) in enumerate(REPLACEMENTS[relative], start=1):
            count = text.count(old)
            if count != 1:
                raise SystemExit(f"{relative}: replacement {index} expected exactly once, found {count}")
            text = text.replace(old, new, 1)
        if text == original:
            raise SystemExit(f"{relative}: declared transformation made no change")
        path.write_text(text, encoding="utf-8")
        changed.append(relative)
    return changed

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path("."))
    args = parser.parse_args()
    root = args.root.resolve()
    changed = apply(root)
    expected = sorted(EXPECTED_BLOBS)
    if changed != expected:
        raise SystemExit(f"changed-path mismatch: expected {expected}, got {changed}")
    print("\n".join(changed))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
